def norm(v: Any) -> str:
    if v is None:
        return ""
    return re.sub(r"\s+", " ", str(v).strip()).casefold()


def safe_name(v: Any) -> str:
    return re.sub(r"[^A-Za-z0-9_.-]+", "_", str(v)).strip("_") or "item"


def normalized_output_prefix(path: Path) -> str:
    stem = path.stem
    for token in [
        "_RECOMMENDED_FINAL_AFTER_BREAKS_SCHEDULE",
        "_BEST_FINAL_AFTER_BREAKS_SCHEDULE",
        "_RECOMMENDED_FINAL",
        "_UNIVERSAL_SCHEDULE",
    ]:
        if stem.endswith(token):
            return stem[:-len(token)]
    return stem


def cleanup_stale_run_outputs(
    output_path: Path, audit_path: Path, summary_csv: Path, work_dir: Path
) -> List[str]:
    """Remove only the known artifacts for an intentional non-resume overwrite."""
    prefix = normalized_output_prefix(output_path)
    known = {
        output_path, audit_path, summary_csv,
        output_path.with_name(prefix + "_BEST_BEFORE_BREAKS_SCHEDULE" + output_path.suffix),
        output_path.with_name(prefix + "_BEST_FINAL_AFTER_BREAKS_SCHEDULE" + output_path.suffix),
        output_path.with_name(prefix + "_RECOMMENDED_FINAL_AFTER_BREAKS_SCHEDULE" + output_path.suffix),
        output_path.with_name(prefix + "_MAX_TARGET_CANDIDATE" + output_path.suffix),
        output_path.with_name(prefix + "_MAX_FLOOR_CANDIDATE" + output_path.suffix),
        output_path.with_name(prefix + "_SAFER_BALANCED_CANDIDATE" + output_path.suffix),
        output_path.with_name(prefix + "_PARETO_EXPORT_MANIFEST.json"),
        output_path.with_name(output_path.stem + "_CANDIDATE_LEADERBOARD.csv"),
    }
    removed: List[str] = []
    for candidate in sorted(known, key=lambda item: str(item)):
        if candidate.exists() and candidate.is_file():
            candidate.unlink()
            removed.append(str(candidate))
        for temporary in candidate.parent.glob(candidate.name + ".tmp*"):
            if temporary.is_file():
                temporary.unlink()
                removed.append(str(temporary))
    for pattern in [f"{prefix}*.publishing*.xlsx", f"{prefix}*.stage*.xlsx", f"{prefix}*.tmp*"]:
        for temporary in output_path.parent.glob(pattern):
            if temporary.is_file():
                temporary.unlink()
                removed.append(str(temporary))
    if work_dir.exists():
        shutil.rmtree(work_dir)
        removed.append(str(work_dir))
    return sorted(set(removed))


def to_float(v: Any, default: float = 0.0) -> float:
    try:
        if v in (None, ""):
            return default
        if isinstance(v, str) and v.strip().endswith("%"):
            return float(v.strip()[:-1]) / 100.0
        return float(v)
    except Exception:
        return default


def yes(v: Any, default: bool = False) -> bool:
    s = norm(v)
    if not s:
        return default
    return s in {"yes", "y", "true", "1", "enabled", "on", "hard", "required"}


def tri_state(v: Any, default: str = "no") -> str:
    s = norm(v)
    if not s:
        return default
    if s in {"auto", "automatic", "instruction driven", "instruction-driven"}:
        return "auto"
    return "yes" if yes(v, False) else "no"


def parse_time_window(value: Any) -> Tuple[Optional[int], Optional[int]]:
    if value in (None, ""):
        return None, None
    values = re.findall(r"(?<!\d)(\d{1,2}):?(\d{2})(?!\d)", str(value))
    if len(values) < 2:
        return None, None
    start = (int(values[0][0]) % 24) * 60 + int(values[0][1])
    end = (int(values[1][0]) % 24) * 60 + int(values[1][1])
    return start, end


def minute_in_inclusive_window(minute: int, start: Optional[int], end: Optional[int]) -> bool:
    if start is None or end is None:
        return True
    minute %= 1440
    if start <= end:
        return start <= minute <= end
    return minute >= start or minute <= end


def shift_start_contract_allows(
    minute: int, start: Optional[int], end: Optional[int], step_minutes: int
) -> bool:
    if not minute_in_inclusive_window(minute, start, end):
        return False
    step = max(1, int(step_minutes or 1))
    anchor = 0 if start is None else start
    return (minute - anchor) % step == 0


def blank_requirement_mode(value: Any) -> str:
    s = norm(value)
    if not s:
        return "allow"
    if "blank" in s and "staff" in s and any(token in s for token in ("no ", "none", "prohibit", "forbid", "must not")):
        return "hard_no_current_week_staffing"
    if yes(value, False):
        return "hard_no_current_week_staffing"
    return "allow"


def minute_of_day(v: Any) -> Optional[int]:
    if v is None or v == "":
        return None
    if isinstance(v, dtime):
        return v.hour * 60 + v.minute
    if isinstance(v, datetime):
        return v.hour * 60 + v.minute
    if isinstance(v, (int, float)):
        x = float(v)
        if 0 <= x < 1.00001:
            return int(round(x * 1440)) % 1440
        if 0 <= x < 1440:
            return int(round(x)) % 1440
    m = re.search(r"(?<!\d)(\d{1,2}):(\d{2})(?!\d)", str(v).strip())
    if m:
        return (int(m.group(1)) % 24) * 60 + int(m.group(2))
    return None


def hhmm(minute: int) -> str:
    minute %= 1440
    return f"{minute // 60:02d}:{minute % 60:02d}"


def cyclic_active_window(active_flags: Sequence[bool], interval_minutes: int) -> Dict[str, Any]:
    """Describe a day's active demand without flattening an overnight block.

    The primary cyclic active span is the complement of the largest circular
    blank bridge.  This makes 14:00-08:00 distinct from true 24/7 demand and
    keeps the same interpretation for 15/30/60-minute workbooks.
    """
    flags = [bool(value) for value in active_flags]
    n = len(flags)
    if n == 0 or not any(flags):
        return {
            "first_active": "", "last_active_end": "", "active_interval_count": 0,
            "full_day_active": False, "active_segment_count": 0,
            "blank_bridge_start": "", "blank_bridge_end": "", "blank_bridge_minutes": 1440,
        }
    active_count = sum(flags)
    segment_count = sum(1 for i, flag in enumerate(flags) if flag and not flags[(i - 1) % n])
    if active_count == n:
        return {
            "first_active": "00:00", "last_active_end": "00:00",
            "active_interval_count": active_count, "full_day_active": True,
            "active_segment_count": 1, "blank_bridge_start": "",
            "blank_bridge_end": "", "blank_bridge_minutes": 0,
        }
    blank_runs: List[Tuple[int, int]] = []
    for i, flag in enumerate(flags):
        if flag or not flags[(i - 1) % n]:
            continue
        length = 0
        while length < n and not flags[(i + length) % n]:
            length += 1
        blank_runs.append((i, length))
    start, length = max(blank_runs, key=lambda row: (row[1], -row[0]))
    bridge_end_index = (start + length) % n
    return {
        "first_active": hhmm(bridge_end_index * interval_minutes),
        "last_active_end": hhmm(start * interval_minutes),
        "active_interval_count": active_count,
        "full_day_active": False,
        "active_segment_count": segment_count,
        "blank_bridge_start": hhmm(start * interval_minutes),
        "blank_bridge_end": hhmm(bridge_end_index * interval_minutes),
        "blank_bridge_minutes": length * interval_minutes,
    }


def shift_parts(label: Any) -> Optional[Tuple[int, int, int]]:
    vals = re.findall(r"(\d{1,2}):(\d{2})", str(label or "").strip())
    if len(vals) < 2:
        return None
    st = (int(vals[0][0]) % 24) * 60 + int(vals[0][1])
    en = (int(vals[1][0]) % 24) * 60 + int(vals[1][1])
    dur = (en - st) % 1440
    if dur == 0:
        dur = 1440
    return st, en, dur


def ceil_units(v: float, scale: int = 100) -> int:
    return int(math.ceil(float(v) * scale - 1e-9))


JOINT_COVERAGE_SCALE = 1_000_000


def scaled_effective_factor(shrinkage: float, scale: int = JOINT_COVERAGE_SCALE) -> int:
    """Integer effective-FTE multiplier aligned with the canonical evaluator.

    RC4.4.2 rounded interval shrinkage to whole percentage points inside the
    joint model. Real workbooks contain fractional shrinkage ratios, so a
    schedule that passed ``calculate_metrics`` could become artificially
    infeasible when replayed by joint CP-SAT. Six-decimal scaling keeps the
    integer model aligned with workbook truth without using floating point.
    """
    return max(0, int(round((1.0 - float(shrinkage)) * int(scale))))


def scaled_coverage_threshold(
    requirement: float, ratio: float, quarter_count: int,
    scale: int = JOINT_COVERAGE_SCALE,
) -> int:
    """Return the exact scaled average-coverage threshold for an interval."""
    return int(math.ceil(
        float(requirement) * float(ratio) * max(1, int(quarter_count)) * int(scale) - 1e-7
    ))


def ensure_parent(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)


def git_repository_identity(start: Optional[Path] = None) -> Dict[str, Any]:
    """Return portable Git provenance without making Git a runtime dependency."""
    repo = (start or Path(__file__).resolve().parent.parent).resolve()
    payload: Dict[str, Any] = {
        "available": False, "commit": None, "describe": None,
        "dirty": None, "repository_root": None,
    }
    try:
        top = subprocess.check_output(
            ["git", "-C", str(repo), "rev-parse", "--show-toplevel"],
            text=True, stderr=subprocess.DEVNULL, timeout=5,
        ).strip()
        commit = subprocess.check_output(
            ["git", "-C", top, "rev-parse", "HEAD"],
            text=True, stderr=subprocess.DEVNULL, timeout=5,
        ).strip()
        describe = subprocess.check_output(
            ["git", "-C", top, "describe", "--always", "--dirty", "--tags"],
            text=True, stderr=subprocess.DEVNULL, timeout=5,
        ).strip()
        status = subprocess.check_output(
            ["git", "-C", top, "status", "--porcelain"],
            text=True, stderr=subprocess.DEVNULL, timeout=5,
        )
        payload.update({
            "available": True, "commit": commit, "describe": describe,
            "dirty": bool(status.strip()), "repository_root": top,
        })
    except Exception as exc:
        payload["error"] = f"{type(exc).__name__}: {exc}"
    return payload


def write_json(path: Path, payload: Any) -> None:
    ensure_parent(path)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, indent=2, default=str), encoding="utf-8")
    tmp.replace(path)


def write_csv(path: Path, rows: Sequence[Dict[str, Any]]) -> None:
    """Atomically write a CSV so stale/partial leaderboard files are never published."""
    ensure_parent(path)
    rows = list(rows)
    fields = sorted({k for r in rows for k in r}) or ["status"]
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=fields)
        w.writeheader()
        for row in rows:
            w.writerow({k: row.get(k, "") for k in fields})
    tmp.replace(path)


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def canonical_hash(payload: Any) -> str:
    raw = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def verify_xlsx(path: Path) -> Dict[str, Any]:
    """Reopen the XLSX as ZIP and workbook; return a release-verification record."""
    if not path.exists() or path.stat().st_size <= 0:
        raise RuntimeError(f"Output workbook is missing or empty: {path}")
    with zipfile.ZipFile(path, "r") as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"Corrupt XLSX member {bad_member} in {path}")
    from openpyxl import load_workbook
    wb = load_workbook(path, read_only=True, data_only=False)
    sheets = list(wb.sheetnames)
    wb.close()
    required = {"Schedule", "Production Summary", "Validation Log", "Candidate Leaderboard"}
    missing = sorted(required - set(sheets))
    if missing:
        raise RuntimeError(f"Verified XLSX is missing release sheets: {missing}")
    return {
        "status": "PASS",
        "path": str(path),
        "size_bytes": path.stat().st_size,
        "sha256": sha256_file(path),
        "sheet_count": len(sheets),
        "sheets": sheets,
        "xlsx_zip_test": "PASS",
        "reopen_test": "PASS",
    }


def atomic_save_workbook(wb: Any, path: Path) -> Dict[str, Any]:
    """Save to a sibling temporary file, verify, then atomically publish."""
    ensure_parent(path)
    tmp = path.with_name(path.stem + ".publishing" + path.suffix)
    if tmp.exists():
        tmp.unlink()
    wb.save(tmp)
    verification = verify_xlsx(tmp)
    os.replace(tmp, path)
    verification = verify_xlsx(path)
    return verification


@dataclass
class Associate:
    index: int
    row: int
    slot: Any
    emp_id: Any
    email: str
    name: str
    tl: str
    language: str
    preferences: List[str] = field(default_factory=lambda: [""] * 7)
    previous_saturday: str = ""
    fixed_schedule: List[str] = field(default_factory=lambda: [""] * 7)
    nesting_group: str = ""


@dataclass
class Shift:
    index: int
    label: str
    start_min: int
    end_min: int
    duration_min: int

    @property
    def start_hour(self) -> int:
        return self.start_min // 60

    @property
    def duration_q(self) -> int:
        return self.duration_min // 15

    @property
    def end_abs_min(self) -> int:
        """Absolute end minute from the shift start day.

        Overnight shifts store ``end_min`` modulo 24 hours, so callers that
        need to detect week-boundary spill must use start + duration rather
        than the clock-face end minute.
        """
        return self.start_min + self.duration_min


@dataclass
class LanguageRule:
    language: str
    group: str
    start_min: int
    end_min: int
    minimum: int
    active: bool
    required_languages: Set[str]
    eligible_languages: Set[str]

    def contains_minute(self, minute: int) -> bool:
        if self.start_min == self.end_min:
            return True
        if self.start_min < self.end_min:
            return self.start_min <= minute < self.end_min
        return minute >= self.start_min or minute < self.end_min

    def overlaps(self, minute: int, span: int = 15) -> bool:
        """True when the slot [minute, minute+span) intersects the rule window.

        Coverage is evaluated per quarter-hour, and every caller passes a
        quarter's START minute. Asking `contains_minute(start)` means a window
        that does not begin on a 15-minute boundary is enforced late: a
        09:10-17:05 rule left the 09:00-09:15 quarter unstaffed even though five
        minutes of it are inside the window, so required coverage was simply
        missing for the first ten minutes of the rule.

        A minimum-staffing requirement must err toward covering, so a slot now
        counts when it overlaps the window at all.

        For a window on a 15-minute boundary this is identical to the old
        behaviour - the half-open ends line up exactly with the slot edges - so
        every language rule in this project is unaffected.
        """
        if self.start_min == self.end_min:
            return True
        width = max(1, int(span))
        start, end = self.start_min, self.end_min
        if end < start:
            end += 1440
        slot_start = minute % 1440
        slot_end = slot_start + width
        # The window may run past midnight, so test the slot in this day and in
        # the next one.
        return ((slot_start < end and start < slot_end)
                or (slot_start + 1440 < end and start < slot_end + 1440))


