def canonical_contract_snapshot(parsed: ParsedInput) -> Dict[str, Any]:
    """Single normalized contract object used by hashes, resume identity and QA."""
    return input_contract_payload(parsed)


def validate_input_contract(parsed: ParsedInput, feasibility: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Fail before CP-SAT when the workbook contract is malformed or provably impossible."""
    failures: List[Dict[str, Any]] = []
    warnings: List[Dict[str, Any]] = []
    if not parsed.associates:
        failures.append({"code": "NO_ROSTER", "detail": "No named roster rows were parsed."})
    if parsed.instructed_headcount <= 0:
        warnings.append({
            "code": "INSTRUCTED_HEADCOUNT_NOT_EXPLICIT",
            "detail": "The named Schedule roster is used, but Count of Associates/Headcount is blank or zero. Add the explicit intended HC for stronger contract validation.",
            "named_roster_rows": len(parsed.associates),
        })
    if parsed.instructed_headcount > 0 and parsed.instructed_headcount != len(parsed.associates):
        row = {
            "code": "HEADCOUNT_MISMATCH",
            "instructed_headcount": parsed.instructed_headcount,
            "named_roster_rows": len(parsed.associates),
            "override_source": parsed.headcount_mismatch_source,
        }
        if parsed.headcount_mismatch_allowed:
            warnings.append(row)
        else:
            failures.append(row)
    if not parsed.shifts:
        failures.append({"code": "NO_LEGAL_SHIFTS", "detail": "No legal shifts were parsed from Shift Library."})
    active_count = sum(sum(1 for value in day if value) for day in parsed.active)
    if active_count <= 0:
        failures.append({"code": "NO_ACTIVE_DEMAND", "detail": "No positive requirement intervals were parsed."})
    if not (0 < parsed.target_ratio <= 1.0):
        failures.append({"code": "INVALID_TARGET_RATIO", "value": parsed.target_ratio})
    if not (0 < parsed.floor_ratio <= parsed.target_ratio + 1e-9):
        failures.append({"code": "INVALID_FLOOR_RATIO", "floor": parsed.floor_ratio, "target": parsed.target_ratio})
    if parsed.target_ratio >= 0.995 and not parsed.target_priority_confirmed:
        warnings.append({
            "code": "TARGET_100_NOT_CONFIRMED",
            "detail": "A 100% target makes the 100% interval tier primary. Confirm the target explicitly in Instructions before production promotion.",
            "target_ratio": parsed.target_ratio,
        })
    if not (
        parsed.target_ratio <= parsed.overage_soft_cap_ratio
        <= parsed.overage_severe_cap_ratio
        <= parsed.overage_extreme_cap_ratio
    ):
        failures.append({
            "code": "INVALID_OVERAGE_CAP_ORDER",
            "target_ratio": parsed.target_ratio,
            "soft_cap_ratio": parsed.overage_soft_cap_ratio,
            "severe_cap_ratio": parsed.overage_severe_cap_ratio,
            "extreme_cap_ratio": parsed.overage_extreme_cap_ratio,
        })
    if parsed.hard_floor_ratio is not None and not (0 < parsed.hard_floor_ratio <= parsed.floor_ratio + 1e-9):
        failures.append({
            "code": "INVALID_HARD_FLOOR_RATIO",
            "hard_floor_ratio": parsed.hard_floor_ratio,
            "configured_floor_ratio": parsed.floor_ratio,
        })
    if parsed.shift_start_step_minutes <= 0:
        failures.append({"code": "INVALID_SHIFT_START_STEP", "value": parsed.shift_start_step_minutes})
    illegal_start_shifts = [
        shift.label for shift in parsed.shifts
        if not shift_start_contract_allows(
            shift.start_min, parsed.allowed_shift_start_min, parsed.allowed_shift_start_end,
            parsed.shift_start_step_minutes,
        )
    ]
    if illegal_start_shifts:
        failures.append({
            "code": "SHIFT_START_CONTRACT_VIOLATION_IN_LEGAL_LIBRARY",
            "count": len(illegal_start_shifts),
            "examples": illegal_start_shifts[:20],
        })
    if parsed.rest_gap_hours < 0 or parsed.rest_gap_hours >= 24:
        failures.append({"code": "INVALID_REST_GAP", "value": parsed.rest_gap_hours})
    if parsed.max_different_shifts <= 0:
        failures.append({"code": "INVALID_MAX_SHIFT_VARIETY", "value": parsed.max_different_shifts})
    break_minutes = sum(q * 15 for q, _ in parsed.break_segments_q)
    min_shift = min((s.duration_min for s in parsed.shifts), default=0)
    if min_shift and break_minutes >= min_shift:
        failures.append({"code": "BREAKS_EXCEED_SHIFT", "break_minutes": break_minutes, "minimum_shift_minutes": min_shift})
    legal = {norm(s.label) for s in parsed.shifts}
    invalid_fixed = []
    for associate in parsed.associates:
        for day, label in enumerate(associate.fixed_schedule):
            if label and norm(label) not in legal and norm(label) not in {"off", "leave", "pto", "vacation"}:
                invalid_fixed.append({"associate": associate.name, "day": DAY_NAMES[day], "value": label})
    if invalid_fixed:
        failures.append({"code": "UNKNOWN_FIXED_SHIFT", "count": len(invalid_fixed), "examples": invalid_fixed[:20]})
    shift_by_label = {norm(shift.label): shift for shift in parsed.shifts}
    fixed_rest_conflicts: List[Dict[str, Any]] = []
    for associate in parsed.associates:
        for day in range(6):
            left = shift_by_label.get(norm(associate.fixed_schedule[day]))
            right = shift_by_label.get(norm(associate.fixed_schedule[day + 1]))
            if left is not None and right is not None and not rest_compatible(left, right, parsed.rest_gap_hours):
                fixed_rest_conflicts.append({
                    "associate": associate.name, "from_day": DAY_NAMES[day], "to_day": DAY_NAMES[day + 1],
                    "from_shift": left.label, "to_shift": right.label,
                })
        saturday = shift_by_label.get(norm(associate.fixed_schedule[6]))
        sunday = shift_by_label.get(norm(associate.fixed_schedule[0]))
        if saturday is not None and sunday is not None and not rest_compatible(saturday, sunday, parsed.rest_gap_hours):
            fixed_rest_conflicts.append({
                "associate": associate.name, "from_day": "Sat", "to_day": "Next Sun",
                "from_shift": saturday.label, "to_shift": sunday.label,
            })
        if sunday is not None and not previous_saturday_compatible(associate.previous_saturday, sunday, parsed.rest_gap_hours):
            fixed_rest_conflicts.append({
                "associate": associate.name, "from_day": "Previous Sat", "to_day": "Sun",
                "from_shift": associate.previous_saturday, "to_shift": sunday.label,
            })
    if fixed_rest_conflicts:
        failures.append({
            "code": "FIXED_CYCLIC_REST_CONFLICT", "count": len(fixed_rest_conflicts),
            "minimum_rest_hours": parsed.rest_gap_hours, "examples": fixed_rest_conflicts[:20],
        })
    nesting_exact: Dict[str, List[Tuple[str, Tuple[str, ...]]]] = {}
    for associate in parsed.associates:
        if associate.nesting_group and any(associate.fixed_schedule):
            nesting_exact.setdefault(norm(associate.nesting_group), []).append(
                (associate.name, tuple(norm(value) for value in associate.fixed_schedule))
            )
    contradictory_groups = []
    for group, rows in nesting_exact.items():
        schedules = {schedule for _, schedule in rows}
        if len(schedules) > 1:
            contradictory_groups.append({"group": group, "members": [name for name, _ in rows]})
    if contradictory_groups:
        failures.append({
            "code": "CONTRADICTORY_EXACT_SCHEDULES_IN_NESTING_GROUP",
            "count": len(contradictory_groups), "examples": contradictory_groups[:20],
        })
    for d in range(7):
        for i in range(parsed.intervals_per_day):
            req = parsed.requirements[d][i]
            shr = parsed.shrinkage[d][i]
            if req is not None and req < 0:
                failures.append({"code": "NEGATIVE_REQUIREMENT", "day": DAY_NAMES[d], "interval": hhmm(i * parsed.interval_minutes), "value": req})
            if not (0 <= shr < 1):
                failures.append({"code": "INVALID_SHRINKAGE", "day": DAY_NAMES[d], "interval": hhmm(i * parsed.interval_minutes), "value": shr})
    language_capacity = []
    for rule in parsed.language_rules:
        eligible = [a for a in parsed.associates if language_eligible(rule, a)]
        language_capacity.append({"group": rule.group, "minimum": rule.minimum, "eligible_count": len(eligible)})
        if len(eligible) < rule.minimum:
            failures.append({
                "code": "LANGUAGE_MINIMUM_EXCEEDS_ELIGIBLE_ROSTER",
                "group": rule.group,
                "minimum": rule.minimum,
                "eligible_count": len(eligible),
                "eligible_associates": [a.name for a in eligible],
            })
        elif len(eligible) <= rule.minimum + 1:
            warnings.append({"code": "LANGUAGE_WINDOW_TIGHT", "group": rule.group, "minimum": rule.minimum, "eligible_count": len(eligible)})
    if parsed.opening_guard_enabled and parsed.opening_minimum > len(parsed.associates):
        failures.append({"code": "OPENING_MINIMUM_EXCEEDS_ROSTER", "minimum": parsed.opening_minimum, "roster_count": len(parsed.associates)})
    for duration_q in sorted({shift.duration_q for shift in parsed.shifts}):
        patterns = _generic_break_patterns(
            duration_q, parsed.break_segments_q, 1,
            window_rules=parsed.break_window_rules_q,
            edge_margin_q=parsed.break_edge_margin_q,
            minimum_gap_q=parsed.break_min_gap_q,
            preferred_gap_q=parsed.break_preferred_gap_q,
            normal_max_gap_q=parsed.break_normal_max_gap_q,
        )
        if not patterns:
            failures.append({
                "code": "BREAK_WINDOW_CONTRACT_INFEASIBLE",
                "shift_duration_minutes": duration_q * 15,
                "source": parsed.break_window_source,
                "segment_windows": parsed.break_window_rules_q,
                "edge_margin_minutes": None if parsed.break_edge_margin_q is None else parsed.break_edge_margin_q * 15,
                "absolute_minimum_gap_minutes": parsed.break_min_gap_q * 15,
                "preferred_gap_minutes": parsed.break_preferred_gap_q * 15,
                "normal_maximum_gap_minutes": parsed.break_normal_max_gap_q * 15,
            })
    if parsed.break_window_source != "instructions":
        warnings.append({
            "code": "BREAK_WINDOWS_USING_DERIVED_DEFAULTS",
            "detail": "Break counts/durations are instruction-driven, but earliest/latest placement windows were not explicitly supplied.",
        })
    next_sunday_preflight = next_sunday_capacity_preflight(parsed)
    failures.extend(next_sunday_preflight.get("failures", []))
    warnings.extend(next_sunday_preflight.get("warnings", []))
    if feasibility:
        failures.extend(feasibility.get("hard_failures", []))
        warnings.extend(feasibility.get("warnings", []))
    return {
        "status": "FAIL" if failures else ("WARN" if warnings else "PASS"),
        "active_interval_count": active_count,
        "break_minutes_per_working_day": break_minutes,
        "failures": failures,
        "warnings": warnings,
        "language_capacity": language_capacity,
        "next_sunday_carry_out_preflight": next_sunday_preflight,
    }


def case_identity_warnings(parsed: ParsedInput, input_path: Path, output_path: Path) -> List[Dict[str, Any]]:
    """Warn when an explicit workbook program identity conflicts with the case/output label."""
    program = norm(parsed.program_name)
    if not program:
        return []
    tokens = [token for token in re.findall(r"[a-z0-9]+", program) if len(token) >= 3]
    if not tokens:
        return []
    case_text = norm(normalized_output_prefix(output_path))
    input_text = norm(input_path.stem)
    case_match = any(token in case_text for token in tokens)
    input_match = any(token in input_text for token in tokens)
    if case_match:
        return []
    return [{
        "code": "PROGRAM_CASE_NAME_MISMATCH",
        "program_name": parsed.program_name,
        "input_workbook": input_path.name,
        "output_case_label": normalized_output_prefix(output_path),
        "input_name_matches_program": input_match,
        "detail": "The workbook's explicit Program/Account Name does not appear in the submitted case/output label. The run may continue, but folders and artifacts can be misleading.",
    }]


def import_cp_sat():
    try:
        from ortools.sat.python import cp_model
        return cp_model
    except Exception as exc:
        raise RuntimeError("OR-Tools is required. In Colab run: pip install -q ortools") from exc


def status_name(cp_model: Any, solver: Any, status: int) -> str:
    try:
        return solver.StatusName(status)
    except Exception:
        return {
            cp_model.OPTIMAL: "OPTIMAL", cp_model.FEASIBLE: "FEASIBLE",
            cp_model.INFEASIBLE: "INFEASIBLE", cp_model.MODEL_INVALID: "MODEL_INVALID",
            cp_model.UNKNOWN: "UNKNOWN",
        }.get(status, str(status))


def preference_kind(value: str) -> str:
    s = norm(value)
    if not s or s in {"none", "planned", "plan", "blank"}:
        return "blank"
    if s == "off":
        return "off"
    if s == "leave":
        return "leave"
    if shift_parts(value):
        return "shift"
    return "other"


def circular_minute_distance(a: int, b: int) -> int:
    diff = abs(a - b) % 1440
    return min(diff, 1440 - diff)


def rest_compatible(prev_shift: Shift, next_shift: Shift, rest_gap_hours: float) -> bool:
    rest = 1440 + next_shift.start_min - (prev_shift.start_min + prev_shift.duration_min)
    return rest + 1e-9 >= rest_gap_hours * 60


def previous_saturday_compatible(previous_label: str, sunday_shift: Shift, rest_gap_hours: float) -> bool:
    parts = shift_parts(previous_label)
    if parts is None:
        return True
    st, _, dur = parts
    previous_end = -1440 + st + dur
    rest = sunday_shift.start_min - previous_end
    return rest + 1e-9 >= rest_gap_hours * 60


def maximum_concurrent_breaks(parsed: ParsedInput, staffed_count: int) -> int:
    """Hard concurrent-break ceiling while preserving at least one working associate."""
    staffed = max(0, int(staffed_count))
    if staffed <= 1:
        return 0
    ratio_cap = max(1, int(math.floor(staffed * parsed.break_max_concurrent_ratio + 1e-9)))
    absolute_cap = max(1, int(parsed.break_max_concurrent_absolute))
    return max(0, min(staffed - 1, ratio_cap, absolute_cap))


def next_sunday_raw_cap(parsed: ParsedInput, interval: int) -> int:
    """Integer-safe raw cap that never conflicts with a harder opening/language minimum."""
    req = float(parsed.requirements[0][interval] or 0.0)
    eff_factor = max(1e-9, 1.0 - float(parsed.shrinkage[0][interval]))
    demand_cap = max(1, int(math.ceil(req * parsed.next_sunday_overage_cap_ratio / eff_factor - 1e-9)))
    hard_minimum = 1
    if bool(getattr(parsed, "opening_guard_enabled", False)):
        try:
            if interval in set(opening_intervals_for_day(parsed, 0)):
                hard_minimum = max(hard_minimum, int(getattr(parsed, "opening_minimum", 1)))
        except (AttributeError, IndexError, TypeError):
            pass
    qpi = max(1, int(getattr(parsed, "qslots_per_interval", 1)))
    interval_minutes = max(15, int(getattr(parsed, "interval_minutes", 15 * qpi)))
    for quarter in range(qpi):
        minute = interval * interval_minutes + quarter * 15
        for rule in getattr(parsed, "language_rules", []):
            if rule.active and rule.contains_minute(minute):
                hard_minimum = max(hard_minimum, int(rule.minimum))
    return max(demand_cap, hard_minimum)


def next_sunday_raw_requirement(parsed: ParsedInput, interval: int, ratio: Optional[float] = None) -> int:
    """Minimum integer raw staffing for one Next-Sunday interval."""
    req = float(parsed.requirements[0][interval] or 0.0)
    if req <= 0:
        return 0
    effective_factor = max(1e-9, 1.0 - float(parsed.shrinkage[0][interval]))
    protected_ratio = float(parsed.target_ratio if ratio is None else ratio)
    return max(1, int(math.ceil(req * protected_ratio / effective_factor - 1e-9)))


def next_sunday_adjacent_raw_limit(
    parsed: ParsedInput, previous_interval: int, current_interval: int
) -> int:
    """Demand-aware adjacent raw-HC movement limit.

    The configured smoothness limit remains authoritative when demand is flat.
    A genuine demand step is allowed to move by the corresponding target-raw
    change, preventing the C2.2.1 contradiction where a required 6-to-2 drop
    was capped at three. Large avoidable jumps such as 16-to-9 remain illegal.
    """
    configured = max(1, int(parsed.next_sunday_max_adjacent_raw_change))
    required_delta = abs(
        next_sunday_raw_requirement(parsed, previous_interval)
        - next_sunday_raw_requirement(parsed, current_interval)
    )
    return max(configured, required_delta)


def whole_week_raw_requirement(parsed: ParsedInput, day: int, interval: int, ratio: Optional[float] = None) -> int:
    if not parsed.active[day][interval]:
        return 0
    req = float(parsed.requirements[day][interval] or 0.0)
    eff = max(1e-9, 1.0 - float(parsed.shrinkage[day][interval] or 0.0))
    return max(1, int(math.ceil(req * float(parsed.target_ratio if ratio is None else ratio) / eff - 1e-9)))


def whole_week_raw_cap(parsed: ParsedInput, day: int, interval: int) -> int:
    if not parsed.active[day][interval]:
        return 0
    req = float(parsed.requirements[day][interval] or 0.0)
    eff = max(1e-9, 1.0 - float(parsed.shrinkage[day][interval] or 0.0))
    target_raw = whole_week_raw_requirement(parsed, day, interval)
    percentage_cap = max(1, int(math.ceil(req * getattr(parsed, "whole_week_overage_cap_ratio", 2.0) / eff - 1e-9)))
    opening_cap = parsed.opening_minimum if parsed.opening_guard_enabled and interval in set(opening_intervals_for_day(parsed, day)) else 0
    language_cap = 0
    minute = interval * parsed.interval_minutes
    for rule in language_rules_at(parsed, minute):
        language_cap = max(language_cap, rule.minimum)
    return max(target_raw, percentage_cap, opening_cap, language_cap)


def whole_week_adjacent_raw_limit(parsed: ParsedInput, day: int, previous_interval: int, current_interval: int) -> int:
    configured = max(1, int(getattr(parsed, "whole_week_max_adjacent_raw_change", 999999)))
    previous_required = whole_week_raw_requirement(parsed, day, previous_interval)
    current_required = whole_week_raw_requirement(parsed, day, current_interval)
    return max(configured, abs(current_required - previous_required))


def shift_covers_week_qslot(day: int, shift: Shift, qslot: int) -> bool:
    start = day * 96 + shift.start_min // 15
    return start <= qslot < start + shift.duration_q


def next_sunday_spill_quarters(parsed: ParsedInput) -> int:
    """Maximum legal Saturday spill into the following Sunday, in 15-minute slots."""
    return max(
        [0]
        + [
            max(0, shift.start_min + shift.duration_min - 1440) // 15
            for shift in parsed.shifts
        ]
    )


def next_sunday_qslot(interval: int, quarter: int, parsed: ParsedInput) -> int:
    return TOTAL_QSLOTS + interval * parsed.qslots_per_interval + quarter


def next_sunday_same_day_shift_can_cover(parsed: ParsedInput, quarter_offset: int) -> bool:
    """Whether a legal next-Sunday shift can cover this quarter without Saturday carry-out.

    The week-boundary guard protects only the handoff window that *must* come
    from current Saturday. A true 24/7 contract with legal 00:00 Sunday starts
    must not be forced to duplicate all early demand on Saturday as well.
    """
    qslot = int(quarter_offset)
    for shift in parsed.shifts:
        if not shift_covers_week_qslot(0, shift, qslot):
            continue
        blocked, _ = demand_fit_blocked(parsed, 0, shift)
        if not blocked:
            return True
    return False


def next_sunday_interval_quarters(parsed: ParsedInput, include_blank: bool = False) -> List[Tuple[int, int, int]]:
    """Return every mirrored Sunday quarter inside the Saturday spill horizon.

    C2.2 incorrectly skipped a quarter whenever a legal Sunday shift could
    theoretically cover it. That disabled the guard for 24/7 cases and audited
    Saturday carry-out in isolation. C2.2.2 always protects the full spill
    horizon and evaluates the cyclic total: Saturday carry-out plus the repeated
    Sunday schedule.
    """
    spill_q = min(96, next_sunday_spill_quarters(parsed))
    rows: List[Tuple[int, int, int]] = []
    if spill_q <= 0:
        return rows
    for interval in range(parsed.intervals_per_day):
        for quarter in range(parsed.qslots_per_interval):
            offset = interval * parsed.qslots_per_interval + quarter
            if offset >= spill_q:
                continue
            if not parsed.active[0][interval] and not include_blank:
                continue
            rows.append((interval, quarter, TOTAL_QSLOTS + offset))
    return rows


def next_sunday_own_qslot(pseudo_qslot: int) -> int:
    """Map a pseudo day-eight quarter to the repeated Sunday quarter."""
    return int(pseudo_qslot) - TOTAL_QSLOTS


def next_sunday_interval_indices(parsed: ParsedInput, include_blank: bool = False) -> List[int]:
    return sorted({interval for interval, _, _ in next_sunday_interval_quarters(parsed, include_blank=include_blank)})


def cyclic_requirement_context(parsed: ParsedInput, qslot: int) -> Optional[Tuple[int, int, int]]:
    """Map a current-week or pseudo-next-Sunday qslot to weekday/interval/minute."""
    if 0 <= qslot < TOTAL_QSLOTS:
        day = qslot // 96
        offset = qslot % 96
    elif TOTAL_QSLOTS <= qslot < CYCLIC_TOTAL_QSLOTS:
        day = 0
        offset = qslot - TOTAL_QSLOTS
    else:
        return None
    minute = offset * 15
    interval = minute // parsed.interval_minutes
    if interval < 0 or interval >= parsed.intervals_per_day:
        return None
    return day, interval, minute


def next_sunday_capacity_preflight(parsed: ParsedInput) -> Dict[str, Any]:
    """Optimistic proof that Saturday assignments can protect next Sunday early demand.

    This intentionally ignores weekly coupling and therefore cannot reject a feasible
    schedule. It only fails when even the most optimistic per-associate Saturday
    choices cannot satisfy a mandatory next-Sunday carry-out rule.
    """
    rows: List[Dict[str, Any]] = []
    failures: List[Dict[str, Any]] = []
    warnings: List[Dict[str, Any]] = []
    spill_q = next_sunday_spill_quarters(parsed)
    if spill_q <= 0:
        return {
            "status": "NOT_APPLICABLE",
            "spill_quarters": 0,
            "spill_minutes": 0,
            "rows": [],
            "failures": [],
            "warnings": [],
        }

    saturday_eligible_by_associate = {
        a: associate_day_eligible_shifts(parsed, associate, 6)
        for a, associate in enumerate(parsed.associates)
    }
    sunday_eligible_by_associate = {
        a: associate_day_eligible_shifts(parsed, associate, 0)
        for a, associate in enumerate(parsed.associates)
    }
    opening = set(opening_intervals_for_day(parsed, 0))
    for interval, quarter, qslot in next_sunday_interval_quarters(parsed, include_blank=True):
        minute = interval * parsed.interval_minutes + quarter * 15
        active = bool(parsed.active[0][interval])
        if not active and parsed.blank_requirement_mode != "hard_no_current_week_staffing":
            continue
        own_qslot = next_sunday_own_qslot(qslot)
        covering = [
            a for a in range(len(parsed.associates))
            if (
                any(shift_covers_week_qslot(6, shift, qslot) for shift in saturday_eligible_by_associate[a])
                or any(shift_covers_week_qslot(0, shift, own_qslot) for shift in sunday_eligible_by_associate[a])
            )
        ]
        row: Dict[str, Any] = {
            "day": "Next Sun",
            "time": hhmm(minute),
            "interval_index": interval,
            "quarter_index": quarter,
            "active": active,
            "optimistic_raw_capacity": len(covering),
        }
        if not active:
            rows.append(row)
            continue
        req = float(parsed.requirements[0][interval] or 0.0)
        eff_factor = 1.0 - parsed.shrinkage[0][interval]
        eff_capacity = len(covering) * eff_factor
        floor_required = req * parsed.floor_ratio
        row.update({
            "required": req,
            "shrinkage": parsed.shrinkage[0][interval],
            "optimistic_effective_capacity": round(eff_capacity, 6),
            "floor_required": round(floor_required, 6),
        })
        if not covering:
            failures.append({
                "code": "NEXT_SUNDAY_ZERO_ACTIVE_PROVABLY_IMPOSSIBLE",
                "day": "Next Sun",
                "interval": hhmm(minute),
                "detail": "No eligible Saturday carry-out or repeated Sunday shift can cover this active next-Sunday quarter.",
            })
        if eff_capacity + 1e-9 < floor_required:
            failures.append({
                "code": "NEXT_SUNDAY_FLOOR_PROVABLY_IMPOSSIBLE",
                "day": "Next Sun",
                "interval": hhmm(minute),
                "required": req,
                "floor_ratio": parsed.floor_ratio,
                "optimistic_effective_capacity": round(eff_capacity, 6),
            })
        if parsed.opening_guard_enabled and interval in opening and len(covering) < parsed.opening_minimum:
            failures.append({
                "code": "NEXT_SUNDAY_OPENING_PROVABLY_IMPOSSIBLE",
                "day": "Next Sun",
                "interval": hhmm(minute),
                "minimum": parsed.opening_minimum,
                "optimistic_raw_capacity": len(covering),
            })
        for rule in language_rules_at(parsed, minute):
            eligible = [a for a in covering if language_eligible(rule, parsed.associates[a])]
            if len(eligible) < rule.minimum:
                failures.append({
                    "code": "NEXT_SUNDAY_LANGUAGE_PROVABLY_IMPOSSIBLE",
                    "day": "Next Sun",
                    "interval": hhmm(minute),
                    "group": rule.group,
                    "minimum": rule.minimum,
                    "optimistic_eligible_capacity": len(eligible),
                })
        rows.append(row)

    deduped: List[Dict[str, Any]] = []
    seen: Set[str] = set()
    for item in failures:
        key = canonical_hash(item)
        if key not in seen:
            seen.add(key)
            deduped.append(item)
    return {
        "status": (
            "FAIL" if deduped else
            ("WARN" if warnings else ("PASS" if rows else "NOT_APPLICABLE"))
        ),
        "spill_quarters": spill_q,
        "spill_minutes": spill_q * 15,
        "rows": rows,
        "failures": deduped,
        "warnings": warnings,
    }


def previous_saturday_covers_qslot(label: str, qslot: int) -> bool:
    parts = shift_parts(label)
    if parts is None:
        return False
    st, _, dur = parts
    start = -96 + st // 15
    return start <= qslot < start + dur // 15


def opening_intervals_for_day(parsed: ParsedInput, day: int) -> List[int]:
    active = [i for i in range(parsed.intervals_per_day) if parsed.active[day][i]]
    if not active or not parsed.opening_guard_enabled or parsed.opening_intervals <= 0:
        return []
    groups: List[List[int]] = []
    current: List[int] = []
    for i in active:
        if not current or i == current[-1] + 1:
            current.append(i)
        else:
            groups.append(current)
            current = [i]
    if current:
        groups.append(current)
    out: List[int] = []
    for group in groups:
        out.extend(group[:parsed.opening_intervals])
    return sorted(set(out))


def language_eligible(rule: LanguageRule, associate: Associate) -> bool:
    return norm(associate.language) in rule.eligible_languages


def language_rules_at(parsed: ParsedInput, minute: int, span: int = 15) -> List[LanguageRule]:
    """Rules in force for the quarter-hour slot beginning at `minute`.

    Overlap, not start-minute containment: see `LanguageRule.overlaps`. Every
    call site passes a quarter start, so the default span is 15.
    """
    return [rule for rule in parsed.language_rules if rule.active and rule.overlaps(minute, span)]


def language_operational_reserve_target(parsed: ParsedInput, rule: LanguageRule) -> int:
    """Return the qualified after-break staffing target for a required language.

    The hard contract remains ``rule.minimum``.  The operational reserve is an
    additional qualified associate objective so unrelated English/bilingual
    surplus cannot disguise a single UK/French/other required-language point
    of failure.  Directional capability eligibility is never widened here.
    """
    extra = int(parsed.language_reserve_extra) if parsed.language_reserve_enabled else 0
    return max(int(rule.minimum), int(rule.minimum) + max(0, extra))


def language_reserve_status(actual: int, minimum: int, reserve_target: int) -> str:
    if actual < minimum:
        return "GAP"
    if actual < reserve_target:
        return "MINIMUM_ONLY"
    return "RESERVE_PROTECTED"


def prior_constant_cover(parsed: ParsedInput, day: int, interval: int, rule: Optional[LanguageRule] = None) -> int:
    if day != 0:
        return 0
    qslot = interval * parsed.qslots_per_interval
    count = 0
    for associate in parsed.associates:
        if rule is not None and not language_eligible(rule, associate):
            continue
        if previous_saturday_covers_qslot(associate.previous_saturday, qslot):
            count += 1
    return count


def coverage_vars_at_qslot(
    parsed: ParsedInput,
    x: Dict[Tuple[int, int, int], Any],
    qslot: int,
    eligible_rule: Optional[LanguageRule] = None,
) -> List[Any]:
    out: List[Any] = []
    for a, associate in enumerate(parsed.associates):
        if eligible_rule is not None and not language_eligible(eligible_rule, associate):
            continue
        for sd in range(7):
            for shift in parsed.shifts:
                if shift_covers_week_qslot(sd, shift, qslot):
                    out.append(x[a, sd, shift.index])
    return out


def coverage_vars(parsed: ParsedInput, x: Dict[Tuple[int, int, int], Any], day: int, interval: int, eligible_rule: Optional[LanguageRule] = None) -> List[Any]:
    qslot = day * 96 + interval * parsed.qslots_per_interval
    return coverage_vars_at_qslot(parsed, x, qslot, eligible_rule)


def cyclic_next_sunday_coverage_vars(
    parsed: ParsedInput,
    x: Dict[Tuple[int, int, int], Any],
    pseudo_qslot: int,
    eligible_rule: Optional[LanguageRule] = None,
) -> List[Any]:
    """Saturday carry-out plus the repeated Sunday decision variables."""
    return (
        coverage_vars_at_qslot(parsed, x, pseudo_qslot, eligible_rule)
        + coverage_vars_at_qslot(parsed, x, next_sunday_own_qslot(pseudo_qslot), eligible_rule)
    )


def shift_day_demand_fit(parsed: ParsedInput, day: int, shift: Shift) -> Dict[str, Any]:
    horizon = CYCLIC_TOTAL_QSLOTS if day == 6 else TOTAL_QSLOTS
    qslots = [
        q for q in range(
            day * 96 + shift.start_min // 15,
            day * 96 + shift.start_min // 15 + shift.duration_q,
        )
        if 0 <= q < horizon
    ]
    active_flags: List[bool] = []
    for qslot in qslots:
        context = cyclic_requirement_context(parsed, qslot)
        active_flags.append(bool(context and parsed.active[context[0]][context[1]]))
    active_q = sum(active_flags)
    max_blank_q = current = 0
    for flag in active_flags:
        if flag:
            current = 0
        else:
            current += 1
            max_blank_q = max(max_blank_q, current)
    total_q = len(active_flags)
    return {
        "active_minutes": active_q * 15,
        "active_ratio": active_q / max(1, total_q),
        "max_blank_minutes": max_blank_q * 15,
        "covered_minutes_in_week": total_q * 15,
    }


def demand_fit_blocked(parsed: ParsedInput, day: int, shift: Shift) -> Tuple[bool, Dict[str, Any]]:
    fit = shift_day_demand_fit(parsed, day, shift)
    strict_blank_block = bool(
        parsed.blank_requirement_mode == "hard_no_current_week_staffing"
        and fit["active_minutes"] < fit["covered_minutes_in_week"]
    )
    fit["blank_requirement_blocked"] = strict_blank_block
    blocked = strict_blank_block or (parsed.demand_fit_guard_enabled and (
        fit["active_minutes"] < parsed.demand_fit_min_active_minutes
        or fit["active_ratio"] + 1e-9 < parsed.demand_fit_min_active_ratio
        or fit["max_blank_minutes"] > parsed.demand_fit_max_blank_minutes
    ))
    return blocked, fit


