def _business_int(value: Any) -> Optional[int]:
    try:
        if value is None or value == "":
            return None
        return int(float(value))
    except (TypeError, ValueError):
        return None


def _business_failure_rows(audit: Dict[str, Any]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    preflight = audit.get("pre_solver_contract_validation") or {}
    rows.extend(row for row in (preflight.get("failures") or []) if isinstance(row, dict))
    capacity = audit.get("capacity_diagnostics") or {}
    rows.extend(row for row in (capacity.get("hard_failures") or []) if isinstance(row, dict))
    return rows


def _business_exception_rows(audit: Dict[str, Any]) -> List[Dict[str, Any]]:
    target = _business_int(audit.get("best_proven_minimum_no_break_exceptions"))
    if target is None:
        target = _business_int(audit.get("best_exception_upper_bound"))
    isolation = audit.get("break_constraint_isolation") or {}
    ranked: List[Tuple[int, List[Dict[str, Any]]]] = []
    for item in isolation.get("skeleton_exception_analysis") or []:
        if not isinstance(item, dict):
            continue
        count = _business_int(item.get("minimum_exception_count"))
        if count is None:
            count = _business_int(item.get("minimum_exception_upper_bound"))
        rows = [row for row in (item.get("exception_cells") or []) if isinstance(row, dict)]
        if count is not None and rows:
            ranked.append((count, rows))
    if ranked:
        ranked.sort(key=lambda pair: (abs(pair[0] - target) if target is not None else pair[0], pair[0]))
        return ranked[0][1]
    ranked = []
    for item in audit.get("minimum_exception_diagnostics") or []:
        if not isinstance(item, dict):
            continue
        count = _business_int(item.get("minimum_exception_count"))
        if count is None:
            count = _business_int(item.get("exception_upper_bound"))
        rows = [row for row in (item.get("selected_exception_rows") or []) if isinstance(row, dict)]
        if count is not None and rows:
            ranked.append((count, rows))
    if ranked:
        ranked.sort(key=lambda pair: (abs(pair[0] - target) if target is not None else pair[0], pair[0]))
        return ranked[0][1]
    return []


def _business_reason_window(reasons: Sequence[Any]) -> Optional[str]:
    cleaned = [str(value).strip() for value in reasons if str(value).strip()]
    if not cleaned:
        return None
    def location(reason: str) -> str:
        marker = reason.rfind(" at ")
        return reason[marker + 4:] if marker >= 0 else reason
    first = location(cleaned[0])
    last = location(cleaned[-1])
    return first if first == last else f"{first} to {last}"


def _business_break_blockers(audit: Dict[str, Any]) -> Dict[str, Any]:
    rows = _business_exception_rows(audit)
    groups: Dict[str, Dict[str, Any]] = {}
    families: Dict[str, int] = {}
    examples: List[Dict[str, Any]] = []
    for row in rows:
        row_groups: Set[str] = set()
        for reason in row.get("critical_reasons") or []:
            match = re.match(r"(.+?) minimum\s+\d+\s+at\s+", str(reason), flags=re.IGNORECASE)
            if match:
                group = match.group(1).strip()
                if group.casefold().startswith("next-sunday "):
                    group = group[len("next-Sunday "):]
                row_groups.add(group)
        for group in row_groups:
            item = groups.setdefault(group, {"group": group, "affected_associate_days": 0, "critical_quarters": 0, "associates": set()})
            item["affected_associate_days"] += 1
            item["critical_quarters"] += sum(1 for reason in (row.get("critical_reasons") or []) if re.match(rf"{re.escape(group)} minimum\s+\d+\s+at\s+", str(reason), flags=re.IGNORECASE) or re.match(rf"next-Sunday {re.escape(group)} minimum\s+\d+\s+at\s+", str(reason), flags=re.IGNORECASE))
            item["associates"].add(str(row.get("associate") or "Unknown"))
        for family in row.get("blocking_families") or []:
            key = str(family)
            families[key] = families.get(key, 0) + 1
        if len(examples) < 8:
            examples.append({
                "associate": row.get("associate"),
                "day": row.get("day"),
                "shift": row.get("shift"),
                "window": _business_reason_window(row.get("critical_reasons") or []),
                "blocking_families": list(row.get("blocking_families") or []),
            })
    group_rows = []
    for item in groups.values():
        group_rows.append({
            "group": item["group"],
            "affected_associate_days": int(item["affected_associate_days"]),
            "critical_quarters": int(item.get("critical_quarters", 0)),
            "associates": sorted(item["associates"]),
        })
    group_rows.sort(key=lambda item: (-item.get("critical_quarters", 0), -item["affected_associate_days"], item["group"]))
    family_rows = [
        {"family": family, "affected_associate_days": count}
        for family, count in sorted(families.items(), key=lambda pair: (-pair[1], pair[0]))
    ]
    return {
        "exception_associate_days": len(rows),
        "language_resource_gaps": group_rows,
        "blocking_families": family_rows,
        "affected_examples": examples,
    }


def _business_contract_message(row: Dict[str, Any]) -> Tuple[str, str, Dict[str, Any], List[str]]:
    code = str(row.get("code") or "INPUT_CONTRACT_FAILURE")
    if code == "LANGUAGE_MINIMUM_EXCEEDS_ELIGIBLE_ROSTER":
        group = str(row.get("group") or "required language")
        minimum = _business_int(row.get("minimum")) or 0
        eligible = _business_int(row.get("eligible_count")) or 0
        gap = max(0, minimum - eligible)
        return (
            f"Not enough eligible {group} resources",
            f"{group} requires at least {minimum} eligible associate(s), but the workbook contains {eligible}. The immediate resource gap is {gap}.",
            {"language_group": group, "minimum_required": minimum, "eligible_roster": eligible, "resource_gap": gap},
            [
                f"Add or correctly tag at least {gap} more {group}-eligible associate(s).",
                "Change the assistance direction only when the business explicitly permits another language group to cover this requirement.",
            ],
        )
    if code in {"LANGUAGE_WINDOW_MAX_CAPACITY_BELOW_MINIMUM", "NEXT_SUNDAY_LANGUAGE_PROVABLY_IMPOSSIBLE"}:
        group = str(row.get("group") or "required language")
        minimum = _business_int(row.get("minimum")) or 0
        maximum = _business_int(row.get("maximum_possible"))
        if maximum is None:
            maximum = _business_int(row.get("optimistic_eligible_capacity")) or 0
        day = str(row.get("day") or "")
        moment = str(row.get("time") or row.get("interval") or "")
        gap = max(0, minimum - maximum)
        return (
            f"{group} coverage is impossible in a required window",
            f"At {day} {moment}, the schedule requires {minimum} {group}-qualified associate(s), but the maximum possible qualified coverage is {maximum}. The resource gap is {gap}.",
            {"language_group": group, "minimum_required": minimum, "maximum_possible": maximum, "resource_gap": gap, "day": day, "time": moment},
            [
                f"Add or overlap {group}-qualified coverage at {day} {moment}.".strip(),
                "Move qualified shifts/OFF days or correct roster skill tags; non-eligible associates cannot satisfy this minimum.",
            ],
        )
    if code == "HEADCOUNT_MISMATCH":
        instructed = _business_int(row.get("instructed_headcount")) or 0
        named = _business_int(row.get("named_roster_rows")) or 0
        return (
            "Roster headcount does not match the instruction",
            f"The instruction requests {instructed} associates, while {named} named roster rows were parsed.",
            {"instructed_headcount": instructed, "named_roster_rows": named, "difference": named - instructed},
            ["Correct the instructed headcount or the named roster before running the solver."],
        )
    if code == "FIXED_CYCLIC_REST_CONFLICT":
        minimum = row.get("minimum_rest_hours")
        example = (row.get("examples") or [{}])[0]
        return (
            "Fixed schedules violate the minimum rest rule",
            f"{row.get('count', 1)} fixed transition(s) conflict with the required {minimum}-hour rest gap. Example: {example.get('associate', 'associate')} from {example.get('from_shift', '?')} on {example.get('from_day', '?')} to {example.get('to_shift', '?')} on {example.get('to_day', '?')}.",
            {"minimum_rest_hours": minimum, "conflict_count": row.get("count"), "example": example},
            ["Change one of the fixed shifts or correct the workbook rule; the solver cannot override an exact fixed request."],
        )
    if code == "CONTRADICTORY_EXACT_SCHEDULES_IN_NESTING_GROUP":
        example = (row.get("examples") or [{}])[0]
        group = example.get("group", "nesting group")
        members = example.get("members") or []
        return (
            "A nesting group contains contradictory exact schedules",
            f"Nesting group '{group}' contains different exact fixed schedules for: {', '.join(map(str, members[:8]))}.",
            {"nesting_group": group, "members": members, "conflict_count": row.get("count")},
            ["Remove exact-fixed associates from the flexible nesting group or make every exact schedule in the group identical."],
        )
    detail = str(row.get("detail") or code.replace("_", " ").title())
    return (
        "The workbook contract cannot be scheduled as submitted",
        detail,
        {"failure_code": code, "evidence": row},
        ["Correct the listed workbook contract issue and rerun the schedule."],
    )


def build_business_outcome(audit: Dict[str, Any], return_code: int) -> Dict[str, Any]:
    status = str(audit.get("status") or ("PASS" if int(return_code) == 0 else "FAIL"))
    outcome: Dict[str, Any] = {
        "schema_version": 1,
        "engine_release": str(audit.get("version") or VERSION),
        "technical_status": status,
        "technical_return_code": int(return_code),
        "production_eligible": False,
        "outcome_code": "ENGINE_OUTCOME_REVIEW_REQUIRED",
        "outcome_category": "ACTION_REQUIRED",
        "headline": "Schedule outcome requires review",
        "plain_language_summary": f"The engine ended with technical status {status}.",
        "requested": {},
        "best_proven": {},
        "gap": {},
        "resource_findings": [],
        "affected_examples": [],
        "recommended_actions": [],
        "technical_reference": {
            "return_code_meaning": "The numeric return code is retained for automation only. Use this business outcome as the primary user-facing result."
        },
    }
    hard_valid_artifact = bool(
        audit.get("artifact_state") == "FINAL_VERIFIED"
        and (audit.get("hard_valid_schedule_exists") is True or int((((audit.get("selected_candidate") or {}).get("output_validation") or {}).get("validation") or {}).get("hard_fail_count", 0) or 0) == 0)
    )
    if int(return_code) == 0 or hard_valid_artifact:
        quality = audit.get("production_quality_gate") or {}
        quality_status = str(quality.get("status") or "NOT_EVALUATED")
        exception_count = int(((audit.get("selected_candidate") or {}).get("no_break_exception_count") or 0))
        # RC8.1 smoke-status hotfix: DEVELOPMENT_SMOKE_COMPLETE_QUALITY_DEBT
        # is an audit phase label, not automatically a release-blocking outcome.
        # Use the explicit production quality gate status as the source of truth
        # so WARN schedules surface as completed-with-warnings instead of
        # misleading QUALITY_BLOCKED outcomes.
        if quality_status == "FAIL":
            outcome.update({
                "outcome_code": "FINAL_SCHEDULE_GENERATED_QUALITY_BLOCKED",
                "outcome_category": "QUALITY_BLOCKED",
                "headline": "A final schedule was generated, but an explicit quality gate blocks release",
                "plain_language_summary": "The schedule is hard-valid, but the workbook explicitly configured one or more operational-quality controls as release-blocking.",
                "resource_findings": (quality.get("failures") or [])[:20],
                "production_eligible": False,
                "recommended_actions": ["Review the explicit FAIL-mode quality gates before production use."],
            })
        elif quality_status == "WARN" or exception_count:
            outcome.update({
                "outcome_code": "FINAL_SCHEDULE_GENERATED_WITH_DECLARED_QUALITY_DEBT",
                "outcome_category": "CONDITIONAL_SUCCESS",
                "headline": "Hard-valid final schedule generated with declared operational warnings",
                "plain_language_summary": f"The schedule passed all hard rules and uses {exception_count} approved no-break associate-day exception(s). Operational-quality findings remain visible as warnings rather than hidden hard failures.",
                "production_eligible": bool(audit.get("artifact_state") == "FINAL_VERIFIED" and quality_status != "FAIL"),
                "resource_findings": (quality.get("warnings") or [])[:20],
                "recommended_actions": ["Review the declared warnings and no-break exception comments during operational approval."],
            })
        else:
            outcome.update({
                "outcome_code": "FINAL_SCHEDULE_GENERATED",
                "outcome_category": "SUCCESS",
                "headline": "Final schedule generated successfully",
                "plain_language_summary": "The schedule completed successfully and passed all current release gates.",
                "production_eligible": bool(audit.get("artifact_state") == "FINAL_VERIFIED" and quality_status == "PASS"),
            })
        return outcome

    failure_rows = _business_failure_rows(audit)
    if status == "FAIL_PRE_SOLVER_CONTRACT" and failure_rows:
        headline, summary, requested, actions = _business_contract_message(failure_rows[0])
        outcome.update({
            "outcome_code": "INPUT_OR_RESOURCE_CONTRACT_GAP",
            "outcome_category": "INPUT_OR_RESOURCE_ACTION_REQUIRED",
            "headline": headline,
            "plain_language_summary": summary,
            "requested": requested,
            "resource_findings": failure_rows[:20],
            "recommended_actions": actions,
        })
        return outcome

    if status in {"FAIL_TESTED_SKELETON_EXCEPTION_LOWER_BOUND_EXCEEDS_CAP", "FAIL_NO_BREAK_FEASIBLE_CANDIDATE", "FAIL_BREAKS_REQUIRE_EXPLICIT_EXCEPTION_FOR_TESTED_SKELETONS"}:
        cap = _business_int(audit.get("operational_no_break_cap"))
        lower = _business_int(audit.get("best_exception_lower_bound"))
        upper = _business_int(audit.get("best_exception_upper_bound"))
        proven = _business_int(audit.get("best_proven_minimum_no_break_exceptions"))
        best = proven if proven is not None else lower
        blockers = _business_break_blockers(audit)
        gap = max(0, best - cap) if best is not None and cap is not None else None
        if status == "FAIL_BREAKS_REQUIRE_EXPLICIT_EXCEPTION_FOR_TESTED_SKELETONS":
            code = "BREAK_EXCEPTION_PERMISSION_REQUIRED"
            headline = "Break exceptions are required but not authorized"
            summary = f"The tested skeletons require at least {best} no-break associate-day exception(s), but the workbook does not permit break exceptions."
        elif cap is not None and best is not None:
            code = "BREAK_EXCEPTION_CAP_GAP"
            headline = "The break plan exceeds the approved exception limit"
            summary = f"Requested maximum no-break associate-days: {cap}. Best proven minimum among the tested skeletons: {best}. The proven gap is {gap}."
        else:
            code = "BREAK_PLAN_NOT_FOUND"
            headline = "No legal final break plan was found"
            summary = "The engine could not find a legal break plan for the tested shift/OFF skeletons within the available search budget."
        language_findings = blockers.get("language_resource_gaps") or []
        if language_findings:
            main = language_findings[0]
            summary += f" Main resource blocker: {main.get('group')} coverage, affecting {main.get('affected_associate_days')} associate-day(s) without qualified backup."
        outcome.update({
            "outcome_code": code,
            "outcome_category": "POLICY_OR_RESOURCE_ACTION_REQUIRED",
            "headline": headline,
            "plain_language_summary": summary,
            "requested": {"maximum_no_break_associate_days": cap, "break_exceptions_allowed": bool((audit.get("input_contract") or {}).get("no_break_permission"))},
            "best_proven": {"minimum_no_break_associate_days_for_tested_skeletons": best, "lower_bound": lower, "upper_bound": upper},
            "gap": {"additional_exception_days_above_approved_cap": gap},
            "resource_findings": language_findings + (blockers.get("blocking_families") or []),
            "affected_examples": blockers.get("affected_examples") or [],
            "recommended_actions": [
                "Add or overlap qualified resources in the named bottleneck windows, especially single-person language coverage.",
                "Change shift/OFF patterns so qualified associates have legal break coverage.",
                "Change the exception cap only through an explicit business decision; the engine will not raise it automatically.",
            ],
        })
        return outcome

    if status == "FAIL_PROTECTED_BENCHMARK_NOT_MET":
        outcome.update({
            "outcome_code": "PROTECTED_KPI_NOT_MET",
            "outcome_category": "QUALITY_BLOCKED",
            "headline": "The schedule did not meet the protected KPI benchmark",
            "plain_language_summary": "Candidate schedules were found, but all were rejected because they fell below a protected before-break or after-break KPI minimum.",
            "requested": {"protected_benchmark": audit.get("quality_benchmark")},
            "recommended_actions": ["Review the protected KPI minimums and failure candidate leaderboard; do not weaken the benchmark without a business decision."],
        })
        return outcome

    if status in {"FAIL_PRODUCTION_QUALITY_GATE", "FAIL_QUALITY_BENCHMARK", "FAIL_AFTER_BREAK_HARD_FLOOR_GAP", "FAIL_AFTER_BREAK_HARD_FLOOR_AND_EXCEPTION_GAP", "FAIL_AFTER_BREAK_HARD_RULE_GAP", "FAIL_AFTER_BREAK_HARD_RULE_AND_EXCEPTION_GAP"}:
        quality = audit.get("production_quality_gate") or {}
        outcome.update({
            "outcome_code": "SCHEDULE_GENERATED_BUT_QUALITY_BLOCKED",
            "outcome_category": "QUALITY_BLOCKED",
            "headline": "The candidate schedule is blocked by production-quality rules",
            "plain_language_summary": "A candidate exists, but it violates one or more protected coverage, language, break, balance, or hard-rule limits.",
            "resource_findings": (quality.get("failures") or [])[:20],
            "recommended_actions": ["Use the quality-gate failures to revise staffing, shifts, breaks, or the input contract before production use."],
        })
        return outcome

    if status == "FAIL_HARD_CONTRACT_INFEASIBLE":
        outcome.update({
            "outcome_code": "HARD_RULE_COMBINATION_INFEASIBLE",
            "outcome_category": "INPUT_OR_POLICY_ACTION_REQUIRED",
            "headline": "No schedule satisfies all hard rules together",
            "plain_language_summary": "The roster and legal shifts are individually readable, but the combined hard-rule contract was proven infeasible by the hard-feasibility probe.",
            "resource_findings": [row for row in (audit.get("constraint_isolation") or []) if isinstance(row, dict)][:20],
            "recommended_actions": ["Review the reported hard-rule families, fixed requests, rest, OFF, language, and boundary requirements before rerunning."],
        })
        return outcome

    if status == "FAIL_HARD_CONTRACT_UNKNOWN":
        probe = audit.get("hard_feasibility_probe") or {}
        outcome.update({
            "outcome_code": "HARD_FEASIBILITY_SEARCH_INCOMPLETE",
            "outcome_category": "SEARCH_INCOMPLETE",
            "headline": "Hard-feasibility search ended UNKNOWN before a release schedule was found",
            "plain_language_summary": "The smoke/runtime budget was not enough to prove feasibility or infeasibility. This is not a mathematical proof that the schedule is impossible.",
            "best_proven": {"probe_status": probe.get("cp_status"), "probe_elapsed_sec": probe.get("elapsed_sec")},
            "resource_findings": [row for row in (audit.get("constraint_isolation") or []) if isinstance(row, dict)][:20],
            "recommended_actions": ["Rerun with the RC8.4 GDI/NMG runtime policy or a longer Quick/Deep budget before changing business rules."],
        })
        return outcome

    if status == "FAIL_STAGE2_TIME_BUDGET_EXHAUSTED":
        outcome.update({
            "outcome_code": "BREAK_SEARCH_TIME_EXHAUSTED",
            "outcome_category": "SEARCH_INCOMPLETE",
            "headline": "The break search did not receive enough guaranteed runtime",
            "plain_language_summary": "Shift skeletons were generated, but the protected break-search phase could not complete within its reserved budget.",
            "recommended_actions": ["Use the final matrix runtime profile or increase the break-search reserve; this is not proof of schedule infeasibility."],
        })
        return outcome

    if status == "FAIL_UNEXPECTED_ENGINE_EXCEPTION":
        outcome.update({
            "outcome_code": "ENGINE_EXECUTION_ERROR",
            "outcome_category": "TECHNICAL_FAILURE",
            "headline": "The engine stopped because of an unexpected technical error",
            "plain_language_summary": str(audit.get("exception_message") or "An unexpected engine exception occurred."),
            "recommended_actions": ["Use the exception type, traceback, and run identity for technical investigation; do not interpret this as staffing infeasibility."],
        })
        return outcome

    outcome["recommended_actions"] = ["Review the business outcome evidence and technical audit; the result is not production eligible."]
    return outcome


def format_business_outcome(outcome: Dict[str, Any]) -> str:
    lines = [str(outcome.get("headline") or "Schedule outcome"), "", str(outcome.get("plain_language_summary") or "")]
    for label, key in [("Requested / configured", "requested"), ("Best proven result", "best_proven"), ("Gap", "gap")]:
        value = outcome.get(key) or {}
        if value:
            lines.extend(["", label + ":", json.dumps(value, ensure_ascii=False, sort_keys=True)])
    findings = outcome.get("resource_findings") or []
    if findings:
        lines.extend(["", "Main blockers:"])
        lines.extend("- " + json.dumps(item, ensure_ascii=False, sort_keys=True) for item in findings[:8])
    examples = outcome.get("affected_examples") or []
    if examples:
        lines.extend(["", "Affected examples:"])
        for item in examples[:8]:
            lines.append(f"- {item.get('associate') or 'Unknown associate'} | {item.get('day') or ''} | {item.get('shift') or ''} | {item.get('window') or ''}".strip(" |"))
    actions = outcome.get("recommended_actions") or []
    if actions:
        lines.extend(["", "Required action:"])
        lines.extend(f"- {action}" for action in actions)
    lines.extend(["", f"Business outcome code: {outcome.get('outcome_code')}", f"Technical status: {outcome.get('technical_status')}", f"Technical return code: {outcome.get('technical_return_code')} (automation reference only)"])
    return "\n".join(lines).strip() + "\n"


def _augment_summary_with_business_outcome(summary_csv: Path, outcome: Dict[str, Any]) -> None:
    if not summary_csv.exists():
        return
    try:
        with summary_csv.open("r", encoding="utf-8-sig", newline="") as handle:
            rows = list(csv.DictReader(handle))
        if not rows:
            return
        for row in rows:
            row["business_outcome_code"] = str(outcome.get("outcome_code") or "")
            row["business_outcome_category"] = str(outcome.get("outcome_category") or "")
            row["business_headline"] = str(outcome.get("headline") or "")
            row["business_message"] = str(outcome.get("plain_language_summary") or "")
            row["production_eligible"] = str(bool(outcome.get("production_eligible"))).upper()
        write_csv(summary_csv, rows)
    except Exception:
        return


def publish_business_outcome(audit_path: Path, summary_csv: Path, work_dir: Path, return_code: int) -> Dict[str, Any]:
    audit: Dict[str, Any] = {}
    if audit_path.exists():
        try:
            audit = json.loads(audit_path.read_text(encoding="utf-8"))
        except Exception:
            audit = {}
    outcome = build_business_outcome(audit, int(return_code))
    text = format_business_outcome(outcome)
    audit["business_outcome"] = outcome
    write_json(audit_path, audit)
    write_json(audit_path.with_name("BUSINESS_OUTCOME.json"), outcome)
    audit_path.with_name("BUSINESS_OUTCOME.txt").write_text(text, encoding="utf-8")
    work_dir.mkdir(parents=True, exist_ok=True)
    write_json(work_dir / "BUSINESS_OUTCOME.json", outcome)
    (work_dir / "BUSINESS_OUTCOME.txt").write_text(text, encoding="utf-8")
    _augment_summary_with_business_outcome(summary_csv, outcome)
    print("\n=== BUSINESS OUTCOME ===", flush=True)
    print(text, flush=True)
    return outcome


def record_unexpected_run_failure(
    audit_path: Path, summary_csv: Path, work_dir: Path, exc: Exception
) -> None:
    """Persist a truthful terminal status for an unexpected engine exception."""
    failure_traceback = "".join(traceback.format_exception(type(exc), exc, exc.__traceback__))
    payload: Dict[str, Any] = {}
    if audit_path.exists():
        try:
            payload = json.loads(audit_path.read_text(encoding="utf-8"))
        except Exception:
            payload = {}
    payload.update({
        "status": "FAIL_UNEXPECTED_ENGINE_EXCEPTION",
        "failed_at": datetime.now().isoformat(),
        "exception_type": type(exc).__name__,
        "exception_message": str(exc),
        "exception_traceback": failure_traceback,
    })
    payload.setdefault("events", []).append({
        "event": "UNEXPECTED_ENGINE_EXCEPTION",
        "at": datetime.now().isoformat(),
        "exception_type": type(exc).__name__,
        "exception_message": str(exc),
    })
    write_json(audit_path, payload)
    write_csv(summary_csv, [{
        "status": payload["status"],
        "audit": str(audit_path),
        "exception_type": type(exc).__name__,
        "exception_message": str(exc),
    }])
    work_dir.mkdir(parents=True, exist_ok=True)
    with (work_dir / "scheduler.log").open("a", encoding="utf-8") as log:
        print(failure_traceback, file=log, flush=True)


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = build_arg_parser().parse_args(argv)
    inputs = list(args.input or [])
    if args.selfcheck:
        payload = selfcheck(inputs)
        print(json.dumps(payload, indent=2, default=str))
        return 0 if payload.get("status") == "PASS" else 2
    if len(inputs) != 1 or not args.output:
        raise SystemExit("Exactly one --input and --output are required")
    input_path = inputs[0]
    work_dir = args.work_dir or args.output.parent / (args.output.stem + "_debug")
    audit = args.audit_json or work_dir / "L6_3_2_3_solver_audit.json"
    summary = args.summary_csv or work_dir / "L6_3_2_3_summary.csv"
    widths = [int(x) for x in str(args.pattern_widths).split(",") if str(x).strip()]
    allow_override: Optional[bool] = None
    if args.allow_no_break_exceptions:
        allow_override = True
    if args.disable_no_break_exceptions:
        allow_override = False
    hc_override: Optional[bool] = None
    if args.allow_headcount_mismatch:
        hc_override = True
    if args.disable_headcount_mismatch_override:
        hc_override = False
    repair_limits = [int(x) for x in str(args.repair_change_limits).split(",") if str(x).strip()]
    profile_names = [x.strip() for x in str(args.skeleton_profiles).split(",") if x.strip()]
    break_modes = [x.strip() for x in str(args.break_objective_modes).split(",") if x.strip()]
    joint_limits = [int(x) for x in str(args.joint_change_limits).split(",") if str(x).strip()]
    terminal_started = time.time()
    return_code = 3
    terminal_exception: Optional[Exception] = None
    try:
        return_code = run_case(
            input_path, args.output, audit, summary, work_dir,
        args.time_limit, args.num_workers, widths,
        allow_override, args.max_no_break_exceptions, args.diagnostics_only,
        skeleton_only=args.skeleton_only, export_top_skeletons=args.export_top_skeletons,
        seed_path=args.seed_workbook,
        use_input_schedule_as_seed=args.use_input_schedule_as_seed,
        repair_change_limits=repair_limits or [2, 4, 6],
        skeleton_profile_names=profile_names or None,
        protected_before80_min=args.protected_before80_min,
        protected_after80_min=args.protected_after80_min,
        break_objective_modes=break_modes or None,
        max_after80_tradeoff_intervals=args.max_after80_tradeoff_intervals,
        min_after90_gain_per_after80_loss=args.min_after90_gain_per_after80_loss,
        post_break_repair=not args.disable_post_break_repair,
        adaptive_no_improvement_attempts=args.adaptive_no_improvement_attempts,
        primary_target_tolerance=args.primary_target_tolerance,
        max_final_before_target_loss=args.max_final_before_target_loss,
        benchmark_workbook=args.benchmark_workbook,
        quick_fallback_workbook=args.quick_fallback_workbook,
        validated_fallback_workbooks=args.validated_fallback_workbook or (),
        include_bundled_fallbacks=not args.disable_bundled_fallbacks,
        minimum_final_before_target=args.minimum_final_before_target,
        minimum_best_before_target=args.minimum_best_before_target,
        minimum_final_before_100=args.minimum_final_before100,
        minimum_final_before_90=args.minimum_final_before90,
        minimum_final_before_80=args.minimum_final_before80,
        minimum_final_after_100=args.minimum_final_after100,
        minimum_final_after_90=args.minimum_final_after90,
        minimum_final_after_80=args.minimum_final_after80,
        minimum_best_before_100=args.minimum_best_before100,
        minimum_best_before_90=args.minimum_best_before90,
        minimum_best_before_80=args.minimum_best_before80,
        quality_benchmark_tolerance=args.quality_benchmark_tolerance,
        target_lock_recovery=not args.disable_target_lock_recovery,
        deterministic_baseline=not args.disable_deterministic_baseline,
        solver_random_seed=args.solver_random_seed,
        exception_search_reserve_sec=args.exception_search_reserve_sec,
        post_break_repair_reserve_sec=args.post_break_repair_reserve_sec,
        target_lock_recovery_reserve_sec=args.target_lock_recovery_reserve_sec,
        finalization_reserve_sec=args.finalization_reserve_sec,
        safe_incumbent=not args.disable_safe_incumbent,
        conflict_refinement=not args.disable_conflict_refinement,
        coordinated_repair=not args.disable_coordinated_repair,
        joint_refinement=not args.disable_joint_refinement,
        safe_incumbent_reserve_sec=args.safe_incumbent_reserve_sec,
        conflict_refinement_reserve_sec=args.conflict_refinement_reserve_sec,
        coordinated_repair_reserve_sec=args.coordinated_repair_reserve_sec,
        coordinated_repair_cycles=args.coordinated_repair_cycles,
        joint_refinement_reserve_sec=args.joint_refinement_reserve_sec,
        joint_change_limits=joint_limits or [8, 16, 24, 36, 54],
        joint_shift_options_per_cell=args.joint_shift_options_per_cell,
        joint_patterns_per_shift=args.joint_patterns_per_shift,
        adaptive_joint_attempts=args.adaptive_joint_attempts,
        adaptive_joint_no_improvement_limit=args.adaptive_joint_no_improvement_limit,
        phase_c_development_smoke=args.phase_c_development_smoke,
            overwrite=args.overwrite, resume=args.resume,
            allow_headcount_mismatch_override=hc_override,
        )
    except Exception as exc:
        terminal_exception = exc
        record_unexpected_run_failure(audit, summary, work_dir, exc)
        traceback.print_exception(type(exc), exc, exc.__traceback__)
        return_code = 3
    finally:
        business_outcome: Optional[Dict[str, Any]] = None
        business_outcome_error: Optional[str] = None
        try:
            business_outcome = publish_business_outcome(audit, summary, work_dir, int(return_code))
        except Exception as outcome_exc:
            business_outcome_error = repr(outcome_exc)
            traceback.print_exception(type(outcome_exc), outcome_exc, outcome_exc.__traceback__)
        terminal_payload: Dict[str, Any] = {
            "version": VERSION,
            "terminal": True,
            "return_code": int(return_code),
            "started_at": datetime.fromtimestamp(terminal_started).isoformat(),
            "completed_at": datetime.now().isoformat(),
            "elapsed_sec": round(time.time() - terminal_started, 6),
            "input": str(input_path), "output": str(args.output),
            "audit": str(audit), "summary": str(summary),
            "exception_type": type(terminal_exception).__name__ if terminal_exception else None,
            "exception_message": str(terminal_exception) if terminal_exception else None,
            "business_outcome": business_outcome,
            "business_outcome_error": business_outcome_error,
            "business_outcome_json": str(audit.with_name("BUSINESS_OUTCOME.json")),
            "business_outcome_text": str(audit.with_name("BUSINESS_OUTCOME.txt")),
        }
        if audit.exists():
            try:
                terminal_payload["engine_status"] = json.loads(audit.read_text(encoding="utf-8")).get("status")
            except Exception:
                terminal_payload["engine_status"] = "AUDIT_UNREADABLE"
        terminal_payload["status"] = terminal_payload.get("engine_status") or (
            "PASS" if int(return_code) == 0 else "FAIL"
        )
        write_json(work_dir / "RUN_TERMINAL_STATUS.json", terminal_payload)
    return return_code


if __name__ == "__main__":
    raise SystemExit(main())
